function header(){return `<header class="topbar"><div class="wrap nav"><a class="logo" href="#home" data-page="home">HTM<span>R</span></a><nav class="navlinks"><a href="#services" data-page="services">Services</a><a href="#industries" data-page="industries">Industries</a><div class="nav-dropdown"><a href="#clients" data-page="clients" class="nav-dropdown-trigger">Clients <span>⌄</span></a><div class="nav-dropdown-menu"><a href="#dentalhi" data-page="dentalhi">Dental Hi-Tech <span>↗</span></a><a href="#cloudlions" data-page="cloudlions">CloudLions <span>↗</span></a><a href="#rvt" data-page="rvt">Real Virtual Team <span>↗</span></a></div></div><a href="#about" data-page="about">About</a><a href="#insights" data-page="insights">Insights</a><a href="#careers" data-page="careers">Careers</a></nav><div class="navright"><a class="btn" href="#contact" data-page="contact">Let's Talk <span>↗</span></a></div><button class="menu-btn" aria-label="Open menu" onclick="document.querySelector('.mobile-menu').classList.toggle('open')">☰</button></div><div class="mobile-menu"><a href="#home" data-page="home">Home</a><a href="#services" data-page="services">Services</a><a href="#industries" data-page="industries">Industries</a><a href="#dentalhi" data-page="dentalhi">Client · Dental Hi-Tech</a><a href="#cloudlions" data-page="cloudlions">Client · CloudLions</a><a href="#rvt" data-page="rvt">Client · Real Virtual Team</a><a href="#about" data-page="about">About</a><a href="#insights" data-page="insights">Insights</a><a href="#careers" data-page="careers">Careers</a><a href="#contact" data-page="contact">Contact</a></div><div class="mega"><div class="wrap mega-inner"><div><p class="eyebrow">EXPLORE CAPABILITIES</p><h3>Technology expertise for your next challenge.</h3><p>Explore the services that help your business stay secure, efficient, and ready for growth.</p></div><div class="mega-grid">${serviceData.map(([id,n])=>`<a href="#${id}" data-page="${id}">${n}<span>↗</span></a>`).join('')}</div></div></div></header>`}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footer-top"><div class="footer-brand"><a class="logo" href="#home" data-page="home">HTM<span>R</span></a><p>Technology, expertise, and support for businesses moving forward.</p></div><div class="footer-col"><b>Services</b>${serviceData.map(([id,n])=>`<a href="#${id}" data-page="${id}">${n}</a>`).join('')}</div><div class="footer-col"><b>Company</b><a href="#industries" data-page="industries">Industries</a><a href="#dentalhi" data-page="dentalhi">Dental Hi-Tech</a><a href="#cloudlions" data-page="cloudlions">CloudLions</a><a href="#rvt" data-page="rvt">Real Virtual Team</a><a href="#about" data-page="about">About HTMR</a><a href="#insights" data-page="insights">Insights</a><a href="#careers" data-page="careers">Careers</a><a href="#contact" data-page="contact">Contact</a></div></div><div class="footer-bottom"><span>© 2026 HTMR. All rights reserved.</span><span><a href="#contact" data-page="contact">Privacy Policy</a><a href="#contact" data-page="contact">Terms & Conditions</a></span></div></div></footer>`}
function ctaBand(title="Let's build a stronger technology foundation for your business.",desc='Tell us what your business needs. Our team is ready to help you identify the right next step.') {return `<section class="cta-band"><div class="wrap cta-inner"><h2>${title}</h2><p>${desc}</p><a class="btn" href="#contact" data-page="contact">Start a Conversation ↗</a></div></section>`}
function servicesList(){return `<div class="service-list">${serviceData.map(([id,n,d],i)=>`<a class="service-row" href="#${id}" data-page="${id}"><span class="num">0${i+1}</span><h3>${n}</h3><p>${d}</p><span class="arrow">↗</span></a>`).join('')}</div>`}
function home(){return `<section class="hero-home"><div class="wrap hero-home-inner"><div class="hero-home-copy"><p class="eyebrow">${pages.home.eyebrow}</p><h1>${pages.home.title}</h1><p class="lead">${pages.home.desc}</p><div class="hero-actions"><a class="btn" href="#services" data-page="services">Explore Our Services ↗</a><a class="hero-text-link" href="#contact" data-page="contact">Let's Talk <span>↗</span></a></div></div><div class="hero-home-visual" aria-label="Image placeholder"><span class="visual-index">HTMR / 01</span><span class="visual-cross">+</span><span class="visual-caption">FULL-WIDTH HERO IMAGE PLACEHOLDER</span><span class="visual-outline"></span></div><div class="hero-home-bottom"><span>PEOPLE · PROCESS · TECHNOLOGY</span><span>SCROLL TO EXPLORE ↓</span></div></div></section><section class="trust"><div class="wrap trust-grid"><p class="small">A technology partner for businesses that need dependable expertise.</p><div class="trust-item"><strong>10+</strong><span>Years of industry experience*</span></div><div class="trust-item"><strong>06</strong><span>Technology specialisms</span></div><div class="trust-item"><strong>IT +</strong><span>Technology & business support</span></div></div></section><section class="section"><div class="wrap"><div class="editorial"><div><p class="eyebrow">ABOUT HTMR</p><h2 class="subhead">More than technology. A partner in your business growth.</h2></div><div><p>For over a decade, HTMR has helped businesses navigate the changing technology landscape. We combine practical IT expertise, strategic thinking, and a people-first approach to deliver solutions that support the way modern organizations work.</p><p style="margin-top:18px">We believe technology should simplify business operations, strengthen security, and create opportunities for growth — not become another challenge to manage.</p><a class="link" style="display:inline-block;margin-top:25px" href="#about" data-page="about">Discover HTMR ↗</a></div></div><div class="about-grid">${photo('photo-meeting','A PEOPLE-FIRST APPROACH')}<div class="info-stack"><div class="info-tile"><span class="eyebrow">01 / TECHNOLOGY THAT WORKS</span><div><h3>Reliable by design.</h3><p>Reliable infrastructure, secure systems, and dependable support designed around business needs.</p></div></div><div class="info-tile dark"><span class="eyebrow">02 / PEOPLE WHO UNDERSTAND</span><div><h3>Expertise with context.</h3><p>Experienced professionals who understand the importance of aligning technology with real business objectives.</p></div></div></div></div></div></section><section class="section alt"><div class="wrap"><div class="section-head"><div><p class="eyebrow">WHAT WE DO</p><h2>Technology expertise for every stage of your business.</h2></div><p>From day-to-day IT support to advanced technology management, HTMR helps organizations build, maintain, and improve their digital environments.</p></div>${servicesList()}</div></section><section class="section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">INDUSTRIES</p><h2>Technology built around the way your business works.</h2></div><p>Every industry has unique operational challenges. We help businesses implement and maintain technology solutions that support their workflows.</p></div><div class="industry-feature"><a class="industry-card" href="#dental" data-page="dental"><div class="placeholder-card-art"><span>IMAGE PLACEHOLDER</span></div><div class="content"><p class="eyebrow">01 / HEALTHCARE</p><h3>Dental & Healthcare</h3><p>Technology solutions designed to support dental practices and protect sensitive information.</p><span class="link">Explore Dental Solutions ↗</span></div></a><a class="industry-card" href="#business" data-page="business"><div class="placeholder-card-art"><span>IMAGE PLACEHOLDER</span></div><div class="content"><p class="eyebrow">02 / BUSINESS</p><h3>Business & Enterprise</h3><p>IT support, infrastructure management, cybersecurity, and technology consulting.</p><span class="link">Explore Capabilities ↗</span></div></a></div></div></section><section class="section alt faq-section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">FREQUENTLY ASKED QUESTIONS</p><h2>What businesses ask before choosing an IT partner.</h2></div><p>Clear answers to common questions about managed IT, security, support, and working with HTMR.</p></div><div class="faq-list">${[['What does managed IT support include?','Managed IT support can include helpdesk assistance, network and device management, system monitoring, maintenance, software support, and guidance on keeping your technology reliable. The exact scope depends on your environment and service requirements.'],['Can HTMR support a business with multiple locations?','HTMR’s infrastructure, cloud, and technology management capabilities can support organizations with distributed teams and locations. The right approach depends on the systems, locations, and support coverage required.'],['Do you provide remote and on-site IT support?','Support needs vary by issue and environment. Contact HTMR to discuss the remote assistance, on-site work, and response arrangements available for your business.'],['How can we improve our company’s cybersecurity?','A practical starting point is to review network and endpoint security, access controls, patching, backups, monitoring, and incident-response readiness. HTMR can help assess the areas that need attention.'],['Can you help with cloud migration and DevOps?','HTMR’s Cloud & DevOps capabilities cover cloud environments, infrastructure management, workflow automation, monitoring, and optimization. Scope and timing depend on your current systems and goals.'],['Do you support existing business software and applications?','Yes. Software & Application Support focuses on maintaining and optimizing applications already used by your business, including troubleshooting, updates, performance monitoring, and integration support.'],['How do we know which service is right for our business?','Start with your biggest operational challenge: unreliable infrastructure, application issues, security risks, data systems, cloud operations, or a technology project that needs direction. HTMR can help identify the relevant area.'],['How do we get started with HTMR?','Use the contact form to describe your business, current technology environment, and main challenges. The HTMR team can then discuss your requirements and possible next steps.']].map((x,i)=>`<details class="faq-item"><summary><span class="faq-num">0${i+1}</span><span>${x[0]}</span><b>+</b></summary><p>${x[1]}</p></details>`).join('')}</div></div></section><section class="section news-section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">INSIGHTS & RESOURCES</p><h2>Ideas and insights for a smarter business.</h2></div><a class="link" href="#insights" data-page="insights">Explore all insights ↗</a></div><div class="home-news-grid">${articles.slice(0,4).map((a,i)=>`<a class="home-news-card" href="#article" data-page="article"><div class="news-art"><span>IMAGE PLACEHOLDER</span><small>0${i+1} / HTMR INSIGHTS</small></div><div class="home-news-meta"><span>${a[0]}</span><span>INSIGHT</span></div><h3>${a[1]}</h3><p>${a[2]}</p><span class="link">Read article ↗</span></a>`).join('')}</div></div></section>${ctaBand()}</main>`}
