data:{challenges:['Business data is spread across disconnected systems','Reporting does not provide a clear operational picture','Data pipelines and analytics tools need ongoing maintenance'],steps:[['Understand','Review your data sources, reporting needs, and existing analytics environment.'],['Structure','Identify priorities across data infrastructure, governance, and analytics tools.'],['Improve','Support reliable data workflows and the systems used to generate insights.']],faqs:[['Can you help maintain existing analytics tools?','The service includes support for dashboards, reporting tools, and business intelligence platforms.'],['Does this service include AI systems?','AI and machine learning systems are included in the listed areas of expertise.'],['Can you help with data pipelines?','Data infrastructure and pipeline support are included in the service offering.']]},
cloud:{challenges:['Cloud environments become difficult to manage as they grow','Manual workflows slow down development and operations','Performance, availability, and costs need closer oversight'],steps:[['Assess','Review your cloud environment, workflows, and operational requirements.'],['Plan','Identify opportunities across architecture, automation, and reliability.'],['Optimize','Support cloud operations and improve workflows as your environment evolves.']],faqs:[['Can you support an existing cloud environment?','Cloud operations, infrastructure management, and hybrid or multi-cloud support are listed capabilities.'],['Does the service include DevOps automation?','DevOps process improvement and automation are included areas of expertise.'],['Can you help with cloud performance?','Cloud monitoring, reliability, and performance engineering are part of the service offering.']]},
leadership:{challenges:['Technology priorities are not clearly connected to business goals','Projects lack coordination across teams and stakeholders','Technology decisions need experienced guidance'],steps:[['Understand','Discuss business objectives, current initiatives, and delivery challenges.'],['Align','Define priorities, responsibilities, and a practical direction for technology work.'],['Guide & Deliver','Support project coordination and ongoing technology decision-making.']],faqs:[['Can you support a specific technology project?','IT project and program management are included areas of expertise.'],['Do you provide strategic technology guidance?','Technology strategy, advisory, and consulting are part of the service offering.'],['Can you work alongside an internal IT team?','The service is designed around organizational goals and project needs; the working arrangement should be discussed with HTMR.']]}
