function servicePage(id){let d=details[id],p=pages[id],extra=serviceEnhancements[id];return `<section class="page-hero"><div class="wrap page-hero-grid"><div><p class="eyebrow">${p.eyebrow}</p><h1>${p.title}</h1><p class="lead">${p.desc}</p><div class="hero-actions"><a class="btn" href="#contact" data-page="contact">Discuss Your Needs ↗</a></div></div>${photo(imageMap[id]||'photo-team',p.eyebrow)}</div></section>
<section class="section challenge-section"><div class="wrap challenge-layout"><div><p class="eyebrow">COMMON CHALLENGES</p><h2>What gets in the way?</h2><p class="section-intro">Common issues this service is designed to help businesses address.</p></div><div class="challenge-list">${extra.challenges.map((x,i)=>`<div class="challenge-item"><span>0${i+1}</span><p>${x}</p></div>`).join('')}</div></div></section>
<section class="section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">AREAS OF EXPERTISE</p><h2>What we help you manage.</h2></div><p>Practical expertise focused on the systems and capabilities your business relies on.</p></div><div class="capabilities">${d.areas.map((a,i)=>`<div class="capability"><span class="num">0${i+1}</span><div><h3>${a[0]}</h3><p>${a[1]}</p></div></div>`).join('')}</div></div></section>
<section class="section dark"><div class="wrap value-grid"><div><p class="eyebrow">BUSINESS VALUE</p><h2>${d.value}</h2></div><ul class="value-list"><li>Improve operational reliability and performance</li><li>Reduce avoidable technical interruptions</li><li>Support secure and consistent operations</li><li>Align technology with business priorities</li></ul></div></section>
<section class="section work-section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">HOW WE WORK</p><h2>A clear path from challenge to action.</h2></div><p>Every engagement starts with understanding your environment and identifying the right priorities.</p></div><div class="work-steps">${extra.steps.map((x,i)=>`<article class="work-step"><span class="num">0${i+1}</span><h3>${x[0]}</h3><p>${x[1]}</p></article>`).join('')}</div></div></section>
<section class="section faq-section"><div class="wrap faq-layout"><div><p class="eyebrow">FAQ</p><h2>Questions about ${serviceData.find(x=>x[0]===id)[1]}.</h2></div><div class="faq-list">${extra.faqs.map((x,i)=>`<details class="faq-item"><summary><span class="faq-num">0${i+1}</span><span>${x[0]}</span><b>+</b></summary><p>${x[1]}</p></details>`).join('')}</div></div></section>
<section class="section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">RELATED SERVICES</p><h2>Connected capabilities.</h2></div><p>Explore complementary areas of expertise across the HTMR service offering.</p></div><div class="related">${serviceData.filter(x=>x[0]!==id).slice(0,3).map(x=>`<a href="#${x[0]}" data-page="${x[0]}"><b>${x[1]}</b><span>Explore service ↗</span></a>`).join('')}</div></div></section>${ctaBand('Have a technology challenge to solve?','Tell us about your environment and the support your business needs.')}`}

function services(){return `<section class="page-hero"><div class="wrap page-hero-grid"><div><p class="eyebrow">OUR SERVICES</p><h1>The technology expertise your business needs.</h1><p class="lead">From reliable IT infrastructure to advanced cybersecurity and cloud solutions, HTMR provides the support and expertise to keep your business moving forward.</p><a class="btn" href="#contact" data-page="contact">Discuss Your Needs ↗</a></div>${photo('photo-server','TECHNOLOGY THAT WORKS')}</div></section><section class="section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">OUR CAPABILITIES</p><h2>Comprehensive technology solutions. One trusted partner.</h2></div><p>We support the technology behind your business — from the systems your team relies on every day to the platforms and infrastructure that drive long-term growth.</p></div>${servicesList()}<div style="margin-top:70px;border-top:1px solid #aaa;padding-top:35px"><div class="editorial"><h2 class="subhead">Not sure where to start?</h2><div><p>We learn about your business and current technology environment, identify the right services and priorities, then help implement, manage, and improve your technology as your needs evolve.</p><a class="link" style="display:inline-block;margin-top:22px" href="#contact" data-page="contact">Talk to an expert ↗</a></div></div></div></div></section>${ctaBand()}`}
function talent(){return `<section class="page-hero"><div class="wrap page-hero-grid"><div><p class="eyebrow">${pages.talent.eyebrow}</p><h1>${pages.talent.title}</h1><p class="lead">${pages.talent.desc}</p><a class="btn" href="#contact" data-page="contact">Find the Right Talent ↗</a></div>${photo('photo-team','PEOPLE · EXPERTISE · GROWTH')}</div></section><section class="section"><div class="wrap editorial"><div><p class="eyebrow">OVERVIEW</p><h2 class="subhead">Build the team your business needs.</h2></div><p>Finding the right professionals can be challenging. Organizations need people who not only have the right skills but also understand business priorities and can contribute to meaningful outcomes.<br><br>HTMR connects businesses with IT professionals, software engineers, cybersecurity specialists, data experts, and technology leaders.<br><br>Whether you need specialized expertise for a project or additional capabilities to support your operations, our goal is to help you access the right talent.</p></div></section><section class="section alt"><div class="wrap"><p class="eyebrow">SPECIALIZED TALENT FIELDS</p><h2 style="max-width:700px;margin-bottom:45px">Expertise across the technology landscape.</h2><div class="capabilities">${['IT & Infrastructure Professionals','Software Engineers','Cybersecurity Specialists','Data Scientists & AI Professionals','Cloud & DevOps Engineers','Technology Leaders & Project Managers'].map((x,i)=>`<div class="capability"><span class="num">0${i+1}</span><div><h3>${x}</h3><p>Specialized professionals aligned with business and technology requirements.</p></div></div>`).join('')}</div></div></section>${ctaBand('Looking for the right people?','Tell us about your staffing needs and the expertise you are looking for.')}`}
function industries(){const groups=[['dental','Dental & Healthcare','Supporting the technology behind better patient care.','Dental and healthcare organizations depend on reliable technology to manage daily operations, protect sensitive information, and deliver consistent patient experiences. HTMR’s specialized solutions address the technical and operational needs of dental practices.',['Dental IT Infrastructure','Practice IT Support','Data Backup & Security','Office Build-Outs','DSO & Multi-Location Support','Virtual Receptionist Solutions'],'photo-dental'],['business','Small & Mid-Sized Businesses','Technology that supports your day-to-day business.','Growing businesses need reliable systems without the complexity of managing every technical challenge internally. HTMR helps organizations maintain infrastructure, support applications, improve security, and make informed technology decisions.',['Managed IT Support','Network & Infrastructure Management','Software Support','Cloud Solutions','Cybersecurity','IT Consulting'],'photo-meeting'],['business','Growing & Multi-Location Businesses','Technology that grows with your organization.','As businesses expand, their technology environments become more complex. HTMR helps organizations support their IT environments, maintain operational consistency, and coordinate technology initiatives.',['Infrastructure Planning','Multi-Location IT Support','Cloud & DevOps','Security & Data Protection','Technology Leadership','Project Management'],'photo-server']];return `<section class="page-hero"><div class="wrap page-hero-grid"><div><p class="eyebrow">${pages.industries.eyebrow}</p><h1>${pages.industries.title}</h1><p class="lead">${pages.industries.desc}</p><a class="btn" href="#contact" data-page="contact">Discuss Your Industry Needs ↗</a></div>${photo('photo-meeting','INDUSTRY-FOCUSED TECHNOLOGY')}</div></section>${groups.map((g,i)=>`<section class="section ${i%2?'alt':''}"><div class="wrap"><div class="editorial"><div><p class="eyebrow">0${i+1} / INDUSTRY</p><h2 class="subhead">${g[2]}</h2><p style="margin-top:22px">${g[3]}</p></div>${photo(g[5],g[1])}</div><div style="margin-top:40px" class="capabilities">${g[4].map((x,j)=>`<div class="capability"><span class="num">0${j+1}</span><div><h3>${x}</h3><p>Solutions aligned with operational requirements and technology priorities.</p></div></div>`).join('')}</div></div></section>`).join('')}${ctaBand()}`}
function about(){return `<section class="page-hero"><div class="wrap page-hero-grid"><div><p class="eyebrow">ABOUT HTMR</p><h1>${pages.about.title}</h1><p class="lead">For over a decade, HTMR has helped businesses connect with the technology expertise they need to operate, adapt, and grow.</p></div>${photo('photo-team','A PEOPLE-FIRST TECHNOLOGY PARTNER')}</div></section><section class="section"><div class="wrap editorial"><div><p class="eyebrow">OUR STORY</p><h2 class="subhead">Helping businesses navigate an evolving technology landscape.</h2></div><p>Technology continues to change the way organizations operate. From everyday infrastructure and security to software, cloud environments, and advanced analytics, businesses need partners who understand both technology and its impact on operations.<br><br>HTMR was built around this need — helping organizations access experienced professionals, dependable technology support, and guidance that aligns with their goals.<br><br>For over a decade, we have focused on connecting businesses with expertise that helps improve operations, strengthen technology environments, and support long-term growth.</p></div></section><section class="section alt"><div class="wrap"><div class="section-head"><div><p class="eyebrow">WHAT WE BELIEVE</p><h2>Technology should make business better.</h2></div><p>Our proposed principles for the way we approach technology and collaboration.</p></div><div class="principles"><div class="principle"><b>01 / Reliability</b><p>Businesses need technology they can depend on. We focus on creating stable, secure, and efficient technology environments.</p></div><div class="principle"><b>02 / Collaboration</b><p>Strong results begin with understanding. We work closely with organizations to understand their challenges and priorities.</p></div><div class="principle"><b>03 / Long-Term Value</b><p>Technology decisions should support more than immediate needs. We help businesses build solutions that remain useful as they evolve.</p></div></div></div></section><section class="section"><div class="wrap case-grid"><div><p class="eyebrow">OUR EXPERTISE</p><h2>A broad range of technology capabilities.</h2><p style="margin-top:20px">From infrastructure and support to security, data, cloud, and technology leadership.</p></div>${photo('photo-server','TECHNOLOGY CAPABILITIES')}</div><div class="wrap" style="margin-top:45px">${servicesList()}</div></section>${ctaBand('Let’s build something better together.','Tell us about the technology challenges and goals shaping your business.')}`}
const articles=[['Cybersecurity','The Hidden Costs of Overlooking IT Audits: Are You Prepared for the Next Cyber Threat?','Regular IT audits help organizations identify vulnerabilities, uncover inefficiencies, and maintain a more secure technology environment.'],['IT Management','The Top 5 Reasons Your Business Needs Server & Workstation Management Now','Understand how proactive management supports reliable systems and productive teams.'],['IT Management','Why 24/7 IT Support is a Must-Have for Business Continuity','Explore the role of responsive support in minimizing disruption and keeping business operations moving.'],['Web Design','Why Your Website Might Be Costing You Clients','A look at common website issues that can create friction and undermine customer confidence.'],['Advisory','Can’t Afford a Full-Time CTO?','How flexible technology leadership can help businesses make better decisions.'],['Technology','Legacy Software: Upgrade or Get Left Behind','Consider the risks, opportunities, and practical factors involved in modernizing legacy systems.']];
function insights(){return `<section class="page-hero"><div class="wrap"><p class="eyebrow">INSIGHTS & RESOURCES</p><h1>${pages.insights.title}</h1><p class="lead">${pages.insights.desc}</p></div></section><section class="section"><div class="wrap"><p class="eyebrow">FEATURED ARTICLE</p><div class="article-grid"><a class="article-feature" href="#article" data-page="article"><div class="placeholder-card-art" aria-label="Image placeholder"><span>IMAGE PLACEHOLDER</span></div><span class="eyebrow">CYBERSECURITY</span><h2 style="font-size:34px">${articles[0][1]}</h2><p>${articles[0][2]}</p><span class="link">Read Article ↗</span></a><div class="article-side">${articles.slice(1,3).map(a=>`<a class="article-mini" href="#article" data-page="article"><span class="eyebrow">${a[0]}</span><h3>${a[1]}</h3><p>${a[2]}</p><span class="small">Read article ↗</span></a>`).join('')}</div></div></div></section><section class="section alt"><div class="wrap"><div class="section-head"><div><p class="eyebrow">LATEST INSIGHTS</p><h2>Ideas for the challenges ahead.</h2></div><p>Practical thinking and perspectives on technology, security, and business operations.</p></div><div class="capabilities">${articles.map((a,i)=>`<a class="capability" href="#article" data-page="article"><span class="num">0${i+1}</span><div><p class="eyebrow">${a[0]}</p><h3>${a[1]}</h3><p>${a[2]}</p><span class="small">Explore article ↗</span></div></a>`).join('')}</div><p class="small" style="margin-top:18px">Article topics are present in the source site's content. Dates and current publication status should be verified before launch.</p></div></section>${ctaBand('Need guidance on a technology decision?','Explore how HTMR can help your business move forward.')}`}
function article(){return `<section class="page-hero"><div class="wrap"><p class="eyebrow">CYBERSECURITY · INSIGHTS</p><h1 style="max-width:1000px">${articles[0][1]}</h1><p class="lead">${articles[0][2]}</p><p class="small" style="margin-top:22px">HTMR Editorial · Publication date to verify · 6 min read (placeholder)</p></div></section><div class="wrap" style="margin-bottom:65px">${photo('photo-security','SECURITY & BUSINESS CONTINUITY')}</div><section class="section"><div class="wrap article-body"><p>Technology environments change constantly. New applications, employees, devices, and infrastructure create complexity that can be difficult to track without a structured review.</p><h2>Why IT audits matter</h2><p>An IT audit provides an opportunity to review the systems, processes, and controls that support daily business operations. It can help identify outdated technology, inconsistent configurations, access concerns, and gaps in documentation.</p><h2>Common risks businesses overlook</h2><p>Technology issues are not always visible until they interrupt operations. Unsupported software, incomplete backups, excessive user permissions, and undocumented infrastructure can create unnecessary exposure.</p><h2>What a comprehensive review should cover</h2><p>A practical review can include infrastructure, workstations, network configuration, application environments, backup practices, security controls, and the processes used to maintain them.</p><h2>Prepare for the next step</h2><p>Start by documenting your current environment, identifying business-critical systems, and clarifying operational priorities. A structured assessment can help turn a broad technology concern into a focused improvement plan.</p><p class="small">Draft article content for prototype purposes. Technical claims and final editorial copy require review.</p></div></section>${ctaBand('Make your IT environment more resilient.','Talk with HTMR about your infrastructure and security priorities.')}`}
function careers(){const jobs=[['Sales Engineer','Technical Sales','Bridge technical solutions and customer requirements, providing pre- and post-sales support.'],['Technical Support Specialist','IT Support','Provide technical assistance across operating systems, networks, and hardware.'],['Receptionist','Administration','Support communication and task coordination for dental offices, primarily in the NY area.']];return `<section class="page-hero"><div class="wrap page-hero-grid"><div><p class="eyebrow">CAREERS AT HTMR</p><h1>${pages.careers.title}</h1><p class="lead">${pages.careers.desc} Explore opportunities across IT, software development, cybersecurity, data, and technology leadership.</p><a class="btn" href="#positions">Explore Open Positions ↓</a></div>${photo('photo-team','PEOPLE · OPPORTUNITY · GROWTH')}</div></section><section class="section"><div class="wrap editorial"><div><p class="eyebrow">WHY WORK WITH HTMR</p><h2 class="subhead">Your next opportunity starts with the right connection.</h2></div><p>Explore career opportunities that match your professional expertise and ambitions. Discover roles across IT infrastructure, software, cybersecurity, cloud, and data. Connect with organizations and projects that allow you to develop your experience.<br><br><span class="small">Proposed employer-facing copy; employment benefits and conditions need confirmation.</span></p></div></section><section class="section alt" id="positions"><div class="wrap"><div class="section-head"><div><p class="eyebrow">OPEN POSITIONS</p><h2>Find your next opportunity.</h2></div><p>Explore the roles listed below. Current vacancy status must be confirmed before publishing.</p></div><div class="job-list">${jobs.map((j,i)=>`<a class="job" href="#job" data-page="job"><div><h3>${j[0]}</h3><span>${j[1]}</span></div><span>ROLE 0${i+1}</span><p>${j[2]}</p><span class="arrow">↗</span></a>`).join('')}</div><p class="small" style="margin-top:18px">These roles were listed in the source content, but the listings are dated 2024. They are prototype entries, not confirmed active vacancies.</p></div></section><section class="section"><div class="wrap editorial"><div><p class="eyebrow">GENERAL APPLICATION</p><h2 class="subhead">Don't see the right opportunity?</h2></div><div><p>We're always interested in connecting with talented professionals. Send us your resume and tell us more about your experience.</p><a class="btn" style="margin-top:24px" href="#contact" data-page="contact">Submit Your Resume ↗</a></div></div></section>${ctaBand('Have expertise to bring to the team?','Connect with HTMR and tell us about your professional experience.')}`}
function job(){return `<section class="page-hero"><div class="wrap"><p class="eyebrow">CAREER OPPORTUNITY · TECHNICAL SALES</p><h1>Sales Engineer</h1><p class="lead">Help businesses understand technology solutions and find the right approach to their technical challenges.</p><div class="hero-actions"><a class="btn" href="#apply">Apply for this role ↓</a><span class="small">Employment type · To be confirmed &nbsp; Location · To be confirmed</span></div></div></section><section class="section"><div class="wrap editorial"><div><p class="eyebrow">ABOUT THE ROLE</p><h2 class="subhead">Connect customer needs with practical technology solutions.</h2></div><div><p>We are looking for a technically skilled Sales Engineer who can connect customer needs with practical technology solutions.</p><p style="margin-top:18px">You will support the sales process, communicate technical capabilities, and help ensure customers receive the right guidance before and after implementation.</p></div></div></section><section class="section alt"><div class="wrap value-grid"><div><p class="eyebrow">RESPONSIBILITIES</p><h2>What you’ll help deliver.</h2></div><ul class="value-list">${['Understand customer requirements and technical challenges','Explain technology solutions to technical and non-technical audiences','Support pre-sales consultations','Assist with technical demonstrations and solution planning','Coordinate with internal teams','Provide post-sales technical support'].map(x=>`<li>${x}</li>`).join('')}</ul></div></section><section class="section" id="apply"><div class="wrap form-layout"><div><p class="eyebrow">APPLICATION</p><h2>Tell us about yourself.</h2><p style="margin-top:20px">Submit your details and resume for consideration. Role requirements and current availability must be confirmed by HTMR.</p></div><form class="formbox" onsubmit="event.preventDefault();this.querySelector('.notice').classList.add('show')"><div class="formrow"><div><label>First Name</label><input required placeholder="First name"></div><div><label>Last Name</label><input required placeholder="Last name"></div></div><label>Email Address</label><input required type="email" placeholder="name@example.com"><label>Phone Number</label><input placeholder="Your phone number"><label>LinkedIn Profile</label><input placeholder="https://linkedin.com/in/..."><label>Resume / CV</label><input type="file"><label>Message</label><textarea placeholder="Tell us about your experience"></textarea><button class="btn" type="submit">Submit Application ↗</button><div class="notice">Thank you. This is a prototype form; no application has been sent.</div></form></div></section>`}
function contact(){return `<section class="page-hero"><div class="wrap"><p class="eyebrow">CONTACT HTMR</p><h1>${pages.contact.title}</h1><p class="lead">${pages.contact.desc}</p></div></section><section class="section"><div class="wrap form-layout"><div><p class="eyebrow">START A CONVERSATION</p><h2>Tell us what your business needs.</h2><p style="margin-top:22px;max-width:420px">For general questions and business inquiries, get in touch with our team. We’ll use the information you provide to understand the right direction for your inquiry.</p><div style="margin-top:45px;border-top:1px solid #aaa;padding-top:18px"><p class="eyebrow">CONTACT INFORMATION</p><p style="margin-bottom:12px">Email · <b>[Confirm official email]</b></p><p style="margin-bottom:12px">Phone · <b>[Confirm official phone]</b></p><p>Location · <b>[Confirm official business address]</b></p><p class="small" style="margin-top:18px">Contact details are placeholders and are not fabricated.</p></div></div><form class="formbox" onsubmit="event.preventDefault();this.querySelector('.notice').classList.add('show')"><p class="eyebrow">YOUR INFORMATION</p><div class="formrow"><div><label>First Name</label><input required placeholder="First name"></div><div><label>Last Name</label><input required placeholder="Last name"></div></div><label>Business Email</label><input required type="email" placeholder="name@company.com"><div class="formrow"><div><label>Phone Number</label><input placeholder="Phone number"></div><div><label>Company Name</label><input placeholder="Company"></div></div><label>Website (Optional)</label><input placeholder="https://"><label>How Can We Help?</label><select required><option value="">Select a service</option>${['IT & Infrastructure','Software & Application Support','Cybersecurity','Data Science & AI','Cloud & DevOps','Technology Leadership & Project Management','Other'].map(x=>`<option>${x}</option>`).join('')}</select><label>Subject</label><input placeholder="How can we help?"><label>Project / Business Requirements</label><textarea placeholder="Tell us about your needs"></textarea><label style="display:flex;gap:10px;align-items:center;font-weight:400"><input type="checkbox" required style="width:auto;margin:0"> I agree to the Privacy Policy.</label><button type="submit" class="btn">Send Inquiry ↗</button><div class="notice">Thank you for reaching out. This is a prototype form; your inquiry has not been sent.</div></form></div></section>`}
function clients(){return `<section class="page-hero"><div class="wrap"><p class="eyebrow">SELECTED CLIENTS</p><h1>Different businesses. Distinct technology needs.</h1><p class="lead">Explore the organizations featured on HTMR’s current website and the services each one provides.</p></div></section><section class="section"><div class="wrap"><div class="home-news-grid client-index">${[['dentalhi','Dental Hi-Tech','Dental IT support, practice infrastructure, cybersecurity, and office technology.'],['cloudlions','CloudLions','IT infrastructure, managed services, software development, virtual leadership, staffing, and marketing.'],['rvt','Real Virtual Team','Virtual receptionists, offshore staffing, and administrative support for dental practices.']].map((x,i)=>`<a class="home-news-card" href="#${x[0]}" data-page="${x[0]}"><div class="news-art"><span>CLIENT PROFILE</span><small>0${i+1} / HTMR</small></div><div class="home-news-meta"><span>CLIENT</span><span>PROFILE</span></div><h3>${x[1]}</h3><p>${x[2]}</p><span class="link">Explore client ↗</span></a>`).join('')}</div></div></section>`}
function relatedPage(id){const data={
dentalhi:{name:'Dental Hi-Tech',eyebrow:'DENTAL TECHNOLOGY',title:'Technology built around the needs of modern dental practices.',intro:'Dental Hi-Tech provides IT support and technology solutions tailored to dental practices. Its offer spans day-to-day support, office setup, infrastructure, security, and communications.',snapshot:[['FOCUS','IT support and technology for dental practices'],['CORE AREAS','Practice support · Infrastructure · Security'],['AUDIENCE','Dental offices and multi-location practices']],challenge:'Dental practices rely on connected technology to manage appointments, patient information, imaging, communications, and everyday operations. Disruptions across these systems can affect both staff workflows and the patient experience.',blocks:[['01','Practice IT Support','Around-the-clock expert support, flexible support plans, preventive maintenance, and IT project management help dental practices keep essential systems running.'],['02','Dental Office Setup & Growth','Startup dental office support, new office build-outs, technology setup and integration, and solutions for Dental Support Organizations.'],['03','Technology, Security & Communications','Data backup and restoration, virtualization, cybersecurity, commercial audio, VoIP systems, and email management support secure and connected practice operations.'],['04','Operational Support','Virtual assistants and technology coordination can help reduce administrative pressure and keep daily workflows moving.']],steps:[['Understand the practice','Review the office setup, technology environment, and operational needs.'],['Plan the right support','Identify relevant infrastructure, security, and support priorities.'],['Set up and support','Coordinate technology needs and ongoing support around practice operations.']],cta:'Build a more reliable technology environment for your dental practice.',tag:'DENTAL PRACTICE IT'},
cloudlions:{name:'CloudLions',eyebrow:'IT & BUSINESS SOLUTIONS',title:'Technology, teams, and services for business growth.',intro:'CloudLions brings together IT infrastructure, managed services, software development, virtual leadership, staffing, and marketing capabilities for startups and established businesses.',snapshot:[['FOCUS','Technology and business support'],['CORE AREAS','IT & Cloud · Managed Services · Software · Leadership'],['AUDIENCE','Startups through established businesses']],challenge:'As businesses grow, technology needs often span infrastructure, software, security, people, and operations. Managing these connected needs can become complex without the right mix of technical and business capabilities.',blocks:[['01','IT Infrastructure & Cloud','Virtualization, cloud computing, office build-outs, VoIP systems, hardware and software procurement, and IT consulting and audits.'],['02','Managed IT & Support','Server and workstation management, 24/7 service desk, on-site and remote support, device and inventory management, backup and recovery, email management, and cybersecurity.'],['03','Software Development','Custom software design and development, integrations, legacy software modernization, mobile applications, eCommerce platforms, and API development.'],['04','Leadership, Staffing & Marketing','Virtual CTO, CMO, and COO services; IT and engineering teams; virtual assistants; website design; social media marketing; video, advertising, email marketing, and PR.']],steps:[['Identify business needs','Understand the organization, its current setup, and immediate priorities.'],['Connect the capabilities','Determine which technology, development, or business support areas are relevant.'],['Coordinate the work','Bring the selected capabilities together around the organization’s goals.']],cta:'Find the right solutions for your business.',tag:'BUSINESS TECHNOLOGY'},
rvt:{name:'Real Virtual Team',eyebrow:'VIRTUAL STAFFING FOR DENTAL PRACTICES',title:'People and remote support for more efficient dental practices.',intro:'Real Virtual Team focuses on virtual staffing for the dental industry, providing trained virtual receptionists and administrative support professionals to support front-desk operations and patient communication.',snapshot:[['FOCUS','Virtual staffing for dental practices'],['CORE AREAS','Reception · Offshore Staffing · Virtual Assistants'],['AUDIENCE','Dental practices seeking remote administrative support']],challenge:'Dental front desks balance patient calls, scheduling, confirmations, insurance questions, and administrative tasks. When these responsibilities compete for attention, the team can have less time for patients in the practice.',blocks:[['01','Dental Receptionist Solutions','Patient scheduling and confirmations, insurance verifications and inquiries, remote reception support, and patient communication.'],['02','Offshore Staffing & Remote Work','Candidate vetting, language and aptitude evaluation, tailored training, and staff replacement are described as part of its staffing offer.'],['03','Virtual Assistant Services','Administrative support, timesheet tracking, ongoing communication, and day-to-day operational assistance.'],['04','Training & Service Model','The site emphasizes tailored training, ongoing support, and flexible staffing. Claims such as 70+ years of combined experience, no setup fees, and free staff changes should be reconfirmed before publication.']],steps:[['Define the role','Identify the practice’s reception or administrative support needs.'],['Select and prepare','Screen candidates and provide role-specific evaluation and training.'],['Integrate support','Coordinate communication and day-to-day tasks with the dental practice.']],cta:'Give your dental team more time to focus on patients.',tag:'REMOTE DENTAL OPERATIONS'}
}[id];return `<section class="client-hero"><div class="wrap client-hero-grid"><div><p class="eyebrow">${data.eyebrow}</p><h1>${data.title}</h1><p class="lead">${data.intro}</p><a class="btn" href="#contact" data-page="contact">Discuss a similar need ↗</a></div><div class="client-hero-art"><span>${data.eyebrow}</span><b>${data.name}</b><small>HTMR / CLIENTS</small></div></div></section>
<section class="section brand-snapshot"><div class="wrap snapshot-layout"><div><p class="eyebrow">BRAND SNAPSHOT</p><h2>At a glance.</h2></div><div class="snapshot-grid">${data.snapshot.map(x=>`<article><span>${x[0]}</span><p>${x[1]}</p></article>`).join('')}</div></div></section>
<section class="section dark challenge-brand"><div class="wrap challenge-brand-inner"><div><p class="eyebrow">THE CHALLENGE</p><h2>Understanding the needs behind the work.</h2></div><p>${data.challenge}</p></div></section>
<section class="section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">WHAT THEY DO</p><h2>Capabilities built around their focus.</h2></div><p>${data.name} brings together services and capabilities relevant to its audience.</p></div><div class="client-blocks">${data.blocks.map(x=>`<article class="client-block"><span class="num">${x[0]}</span><div><p class="eyebrow">${data.tag}</p><h2>${x[1]}</h2><p>${x[2]}</p></div><span class="client-block-mark">↗</span></article>`).join('')}</div></div></section>
<section class="section work-section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">HOW IT WORKS</p><h2>A practical path from need to support.</h2></div><p>A simple overview of how the organization’s capabilities can come together.</p></div><div class="work-steps">${data.steps.map((x,i)=>`<article class="work-step"><span class="num">0${i+1}</span><h3>${x[0]}</h3><p>${x[1]}</p></article>`).join('')}</div></div></section>${ctaBand(data.cta,'Explore the capabilities and discuss the support that fits your needs.')}`}


function render(id){let body=id==='home'?home():serviceData.some(x=>x[0]===id)?servicePage(id):({services:services,clients:clients,industries:industries,dental:()=>industries(),business:()=>industries(),about:about,insights:insights,article:article,careers:careers,job:job,contact:contact,dentalhi:()=>relatedPage('dentalhi'),cloudlions:()=>relatedPage('cloudlions'),rvt:()=>relatedPage('rvt')}[id]||home)();document.getElementById('app').innerHTML=header()+`<main>${body}</main>`+footer();document.title=(pages[id]?.eyebrow||'HTMR')+' — HTMR';window.scrollTo({top:0,behavior:'instant'});document.querySelectorAll('[data-page]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();const target=a.dataset.page;location.hash=target;render(target);document.querySelector('.mobile-menu')?.classList.remove('open')}));const servicesLink=[...document.querySelectorAll('.navlinks a')].find(a=>a.textContent.trim()==='Services');servicesLink?.addEventListener('mouseenter',()=>document.querySelector('.mega')?.classList.add('open'));document.querySelector('.mega')?.addEventListener('mouseleave',()=>document.querySelector('.mega')?.classList.remove('open'));}
window.addEventListener('hashchange',()=>{let id=location.hash.replace('#','')||'home';if(pages[id]||['services','clients','article','job'].includes(id))render(id)});
render(location.hash.replace('#','')||'home');
